#!/usr/bin/env python3
# Copyright (c) Microsoft Corporation. All rights reserved.
# Licensed under the MIT License. See License.txt in the project root.
"""Bounded read-only system inventory. No network, installation or cleanup."""

import argparse
import base64
from datetime import datetime, timezone
import json
from itertools import islice
import os
from pathlib import Path
import platform
import plistlib
import re
import subprocess
import sys
import time

VERSION = "1.0.1"
LIMIT = 150


def run(argv, timeout=20):
    # Fixed argv only; no shell, user-supplied commands, or stderr in reports.
    result = subprocess.run(argv, stdin=subprocess.DEVNULL, capture_output=True,
                            timeout=timeout, encoding="utf-8", errors="replace",
                            env={**os.environ, "LC_ALL": "C", "LANG": "C"})
    if result.returncode:
        raise ValueError("command_failed")
    if len(result.stdout) > 2 * 1024 * 1024:
        raise ValueError("output_limit")
    return result.stdout.lstrip("\ufeff").strip()


def unavailable(error):
    reason = "timeout" if isinstance(error, subprocess.TimeoutExpired) else "unavailable_or_access_denied"
    return {"status": "unavailable", "reason": reason}


def attempt(callback):
    try:
        return {"status": "ok", "data": callback()}
    except (OSError, ValueError, KeyError, TypeError, subprocess.SubprocessError, plistlib.InvalidFileException) as error:
        return unavailable(error)


def rows(value):
    return value if isinstance(value, list) else [] if value is None else [value]


def text(value):
    return str(value)[:160] if isinstance(value, (str, int, float)) else None


def number(value):
    try:
        result = int(value)
        return result if result >= 0 else None
    except (ValueError, TypeError):
        return None


def disk(name, size, free):
    size, free = number(size), number(free)
    valid = size is not None and free is not None and size > 0 and free <= size
    return {"name": name, "total_bytes": size, "free_bytes": free,
            "free_percent": round(free / size * 100, 1) if valid else None,
            "low_space": free / size < .1 if valid else None}


WINDOWS_QUERY = r"""
$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new()
$result=[ordered]@{}
function Section($key, $query) {
    try { $result[$key]=@{status='ok';data=(& $query)} }
    catch { $result[$key]=@{status='unavailable';reason='unavailable_or_access_denied'} }
}
Section 'hardware' { @{computer=(Get-CimInstance Win32_ComputerSystem | Select-Object Manufacturer,Model,TotalPhysicalMemory);os=(Get-CimInstance Win32_OperatingSystem | Select-Object Caption,Version,FreePhysicalMemory);cpu=@(Get-CimInstance Win32_Processor | Select-Object Name,NumberOfCores,NumberOfLogicalProcessors);gpu=@(Get-CimInstance Win32_VideoController | Select-Object Name)} }
Section 'disks' { @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' | Select-Object DeviceID,Size,FreeSpace) }
Section 'processes' { @(Get-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First 8 ProcessName,WorkingSet64) }
Section 'startup' { @(Get-CimInstance Win32_StartupCommand | Select-Object -First 150 Name,Location) }
Section 'tasks' { @(Get-ScheduledTask | Where-Object { @($_.Triggers | Where-Object { $_.CimClass.CimClassName -in @('MSFT_TaskBootTrigger','MSFT_TaskLogonTrigger') }).Count -gt 0 } | Select-Object -First 150 TaskName,@{Name='State';Expression={$_.State.ToString()}}) }
Section 'approvals' {
    @(foreach ($scope in @('HKCU','HKLM')) {
        foreach ($kind in @('Run','Run32','StartupFolder')) {
            $source = $scope + ':' + $kind
            $path = $scope + ':\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\' + $kind
            try {
                $key = Get-Item -LiteralPath $path -ErrorAction Stop
                $names = @($key.GetValueNames() | Select-Object -First 151)
                $records = @(foreach ($name in ($names | Select-Object -First 150)) {
                    $value = $key.GetValue($name)
                    $code = $null
                    if ($value -is [byte[]] -and $value.Length -gt 0) { $code = [int]$value[0] }
                    @{name=$name;code=$code}
                })
                @{source=$source;status='ok';truncated=($names.Count -gt 150);records=$records}
            } catch [System.Management.Automation.ItemNotFoundException] {
                @{source=$source;status='absent';records=@()}
            } catch {
                @{source=$source;status='unavailable';records=@()}
            }
        }
    })
}
$result | ConvertTo-Json -Depth 8 -Compress
"""


def windows_approvals(section):
    # These registry flags are hints, not proof of execution or an OS API contract.
    allowed = {scope + ':' + kind for scope in ('HKCU', 'HKLM') for kind in ('Run', 'Run32', 'StartupFolder')}
    coverage = {source: 'unavailable' for source in sorted(allowed)}
    records = []
    if section.get('status') != 'ok':
        return records, coverage
    for group in rows(section.get('data')):
        source = group.get('source')
        if source not in allowed:
            continue
        status = group.get('status')
        coverage[source] = 'bounded' if status == 'ok' and group.get('truncated') else status if status in ('ok', 'absent') else 'unavailable'
        if status != 'ok':
            continue
        for item in rows(group.get('records'))[:LIMIT]:
            code = number(item.get('code'))
            hint = 'enabled_hint' if code in (2, 6) else 'disabled_hint' if code in (3, 7) else 'unknown'
            records.append({'name': text(item.get('name')), 'source': source, 'code': code, 'state_hint': hint})
    return records, coverage


def windows(run_command=run):
    executable = Path(os.environ.get("SystemRoot", r"C:\Windows")) / "System32/WindowsPowerShell/v1.0/powershell.exe"
    encoded = base64.b64encode(WINDOWS_QUERY.encode("utf-16-le")).decode("ascii")
    try:
        raw = json.loads(run_command([str(executable), "-NoProfile", "-NonInteractive", "-EncodedCommand", encoded], timeout=45))
        if not isinstance(raw, dict):
            raise ValueError("unexpected_inventory")
    except (OSError, ValueError, subprocess.SubprocessError) as error:
        return {name: unavailable(error) for name in ("hardware", "disks", "processes", "startup")}
    hardware = raw.get("hardware", {})
    if hardware.get("status") == "ok":
        data = hardware["data"]
        computer, os_info = data.get("computer") or {}, data.get("os") or {}
        hardware = {"status": "ok", "data": {
            "manufacturer": text(computer.get("Manufacturer")), "model": text(computer.get("Model")),
            "os": text(os_info.get("Caption")), "os_version": text(os_info.get("Version")),
            "memory_total_bytes": number(computer.get("TotalPhysicalMemory")),
            "memory_available_bytes": (number(os_info.get("FreePhysicalMemory")) or 0) * 1024 if os_info.get("FreePhysicalMemory") is not None else None,
            "cpu": [{"name": text(item.get("Name")), "physical_cores": number(item.get("NumberOfCores")), "logical_cores": number(item.get("NumberOfLogicalProcessors"))} for item in rows(data.get("cpu"))],
            "gpu": [text(item.get("Name")) for item in rows(data.get("gpu"))],
        }}
    else:
        hardware = {"status": "unavailable", "reason": "unavailable_or_access_denied"}
    disks = raw.get("disks", {})
    if disks.get("status") == "ok":
        disks = {"status": "ok", "data": [disk(text(item.get("DeviceID")), item.get("Size"), item.get("FreeSpace")) for item in rows(disks.get("data"))]}
    else:
        disks = {"status": "unavailable", "reason": "unavailable_or_access_denied"}
    processes = raw.get("processes", {})
    if processes.get("status") == "ok":
        processes = {"status": "ok", "data": [{"name": text(item.get("ProcessName")), "memory_bytes": number(item.get("WorkingSet64"))} for item in rows(processes.get("data"))[:8]]}
    else:
        processes = {"status": "unavailable", "reason": "unavailable_or_access_denied"}
    startup = raw.get("startup", {})
    tasks = raw.get("tasks", {})
    items = [{"name": text(item.get("Name")), "source": "Win32_StartupCommand", "state": "configured_enabled_unknown"} for item in rows(startup.get("data"))[:LIMIT]] if startup.get("status") == "ok" else []
    if tasks.get("status") == "ok":
        items += [{"name": text(item.get("TaskName")), "source": "boot_logon_task", "state": text(item.get("State"))} for item in rows(tasks.get("data"))[:LIMIT]]
    coverage = {"Win32_StartupCommand": startup.get("status", "unavailable"), "boot_logon_tasks": tasks.get("status", "unavailable")}
    approvals, approval_coverage = windows_approvals(raw.get('approvals') or {})
    return {"hardware": hardware, "disks": disks, "processes": processes,
            "startup": {"status": "partial", "data": items, "coverage": coverage,
                        "approval_records": approvals, "approval_coverage": approval_coverage,
                        "limit_per_source": LIMIT, "not_checked": ["modern_startup_registrations", "all_users_and_services", "effective_startup_execution", "other_users_startup_approval"]}}


def mac_hardware(run_command):
    raw = json.loads(run_command(["/usr/sbin/system_profiler", "-json", "-detailLevel", "mini", "SPHardwareDataType", "SPDisplaysDataType"]))
    hardware = rows(raw.get("SPHardwareDataType"))
    if not hardware:
        raise ValueError("hardware_unavailable")
    item = hardware[0]
    read = lambda key: run_command(["/usr/sbin/sysctl", "-n", key])
    return {"manufacturer": "Apple", "model": text(item.get("machine_name")), "model_identifier": text(item.get("machine_model")),
            "os": "macOS", "os_version": run_command(["/usr/bin/sw_vers", "-productVersion"]),
            "cpu": [{"name": text(item.get("chip_type") or item.get("cpu_type")), "physical_cores": number(read("hw.physicalcpu")), "logical_cores": number(read("hw.logicalcpu"))}],
            "memory_total_bytes": number(read("hw.memsize")),
            "gpu": [text(row.get("sppci_model") or row.get("_name")) for row in rows(raw.get("SPDisplaysDataType"))]}


def parse_df(output, role):
    lines = output.splitlines()
    if len(lines) != 2:
        raise ValueError("unexpected_df")
    parts = lines[1].split(None, 5)
    if len(parts) != 6:
        raise ValueError("unexpected_df")
    return disk(role, int(parts[1]) * 1024, int(parts[3]) * 1024)


def mac_processes(run_command):
    output = run_command(["/bin/ps", "-axo", "rss=,comm="])
    result = []
    for line in output.splitlines():
        parts = line.strip().split(None, 1)
        if len(parts) == 2 and parts[0].isdigit():
            result.append({"name": Path(parts[1]).name, "memory_bytes": int(parts[0]) * 1024})
    return sorted(result, key=lambda row: row["memory_bytes"], reverse=True)[:8]


def mac_startup(run_command, roots=None):
    roots = roots if roots is not None else [("user_agents", Path.home() / "Library/LaunchAgents"), ("shared_agents", Path("/Library/LaunchAgents")), ("system_daemons", Path("/Library/LaunchDaemons"))]
    try:
        output = run_command(["/bin/launchctl", "list"])
        loaded = {parts[2] for line in output.splitlines()[1:] if len(parts := line.split(None, 2)) == 3}
    except (OSError, ValueError, subprocess.SubprocessError):
        loaded = None
    coverage = {"current_user_launchctl": "ok" if loaded is not None else "unavailable"}
    items = []
    skipped = 0
    for source, root in roots:
        try:
            try:
                root.stat()
            except FileNotFoundError:
                coverage[source] = "absent"
                continue
            candidates = sorted(islice(root.glob("*.plist"), LIMIT + 1))
            coverage[source] = "bounded" if len(candidates) > LIMIT else "ok"
            for file in candidates[:LIMIT]:
                try:
                    if file.is_symlink() or file.stat().st_size > 256 * 1024:
                        skipped += 1
                        continue
                    with file.open("rb") as handle:
                        data = plistlib.load(handle)
                    label = data.get("Label")
                    if not isinstance(label, str):
                        skipped += 1
                        continue
                    # launchctl's current-user domain says nothing about system daemons.
                    state = "unknown" if loaded is None or source == "system_daemons" else "loaded_in_user_domain" if label in loaded else "not_loaded_in_user_domain"
                    items.append({"name": label[:160], "source": source, "state": state,
                                  "run_at_load_hint": data.get("RunAtLoad") is True,
                                  "keep_alive_hint": bool(data.get("KeepAlive"))})
                except (OSError, ValueError, TypeError, AttributeError, plistlib.InvalidFileException):
                    skipped += 1
        except OSError:
            coverage[source] = "unavailable"
    return {"status": "partial", "data": items, "coverage": coverage, "skipped": skipped,
            "limit_per_source": LIMIT, "not_checked": ["modern_login_items_and_background_registrations", "other_user_domains", "enabled_state"]}


def mac(run_command=run):
    volumes = {role: attempt(lambda path=path, role=role: parse_df(run_command(["/bin/df", "-kP", path]), role)) for role, path in (("system", "/"), ("data", "/System/Volumes/Data"))}
    return {"hardware": attempt(lambda: mac_hardware(run_command)),
            "disks": {"status": "partial" if any(value["status"] != "ok" for value in volumes.values()) else "ok", "volumes": volumes, "shared_apfs_space_do_not_sum": True},
            "processes": attempt(lambda: mac_processes(run_command)),
            "startup": mac_startup(run_command)}


def redact(value, home=None):
    if isinstance(value, dict):
        return {key: redact(item, home) for key, item in value.items()}
    if isinstance(value, list):
        return [redact(item, home) for item in value]
    if not isinstance(value, str):
        return value
    home = str(Path.home()) if home is None else home
    value = re.sub(re.escape(home), "<home>", value, flags=re.I) if home else value
    value = re.sub(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}", "<email>", value)
    value = re.sub(r"\b[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}\b", "<id>", value, flags=re.I)
    value = re.sub(r"\bS-\d+-\d+(?:-\d+)+\b", "<sid>", value, flags=re.I)
    return re.sub(r"[\x00-\x1f\x7f]", " ", value)[:200]


def check(system=None, run_command=run):
    started = time.monotonic()
    system = platform.system() if system is None else system
    if system == "Windows":
        sections = windows(run_command)
    elif system == "Darwin":
        sections = mac(run_command)
    else:
        sections = {"hardware": {"status": "unavailable", "reason": "unsupported_platform"}}
    return redact({"schema_version": 1, "helper_version": VERSION, "mode": "read_only",
                   "platform": system, "architecture": platform.machine(),
                   "collected_at": datetime.now(timezone.utc).isoformat(),
                   "elapsed_seconds": round(time.monotonic() - started, 2), "sections": sections,
                   "privacy": "Selected hardware and app/service names only. No document contents, serial/account/host fields or process arguments collected. Labels may still identify installed software or personal information; this report is not anonymous.",
                   "limitations": ["No cleanup or startup changes", "Startup coverage is partial", "A snapshot is not a performance benchmark, malware scan or SSD health test"]})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=["check", "capabilities"])
    parser.add_argument("--output", type=Path, help="Save a new JSON report; never overwrite")
    args = parser.parse_args()
    if args.command == "capabilities":
        report = {"helper_version": VERSION, "mode": "description_only", "platforms": ["Windows", "macOS"],
                  "capabilities": ["hardware_and_os", "disk_free_space", "top_memory_processes", "partial_startup_inventory"],
                  "not_supported": ["cleanup", "startup_changes", "installation", "malware_or_ssd_health_scan", "document_scan"]}
    else:
        report = check()
    # Compact ASCII JSON avoids code-page failures and unnecessary tool-output paging.
    output = json.dumps(report, ensure_ascii=True, separators=(",", ":")) + "\n"
    if args.output:
        with args.output.open("x", encoding="utf-8") as handle:
            handle.write(output)
    print(output, end="")
    return 0 if args.command == "capabilities" or report["sections"].get("hardware", {}).get("status") == "ok" else 2


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (OSError, ValueError) as error:
        print(json.dumps({"status": "failed", "reason": type(error).__name__, "instruction": "No system changes performed; choose a new writable report file or inspect unavailable sections."}), file=sys.stderr)
        sys.exit(2)

#!/usr/bin/env python3
# Copyright (c) Microsoft Corporation. Licensed under the MIT License.
"""Plan and journal reversible, non-overwriting moves inside one folder."""
import argparse
import hashlib
import json
from pathlib import Path
import sys

LIMIT = 500
MAX_BYTES = 64 * 1024**2
CATEGORIES = {'.pdf': 'Documents', '.txt': 'Documents', '.docx': 'Documents', '.md': 'Documents',
              '.csv': 'Tables', '.tsv': 'Tables', '.xlsx': 'Tables', '.pptx': 'Presentations',
              '.jpg': 'Images', '.jpeg': 'Images', '.png': 'Images', '.webp': 'Images',
              '.mp4': 'Videos', '.mov': 'Videos', '.mp3': 'Audio', '.wav': 'Audio', '.zip': 'Archives'}


def dump_new(path, data):
    with Path(path).open('x', encoding='utf-8') as handle:
        json.dump(data, handle, ensure_ascii=True, indent=2)


def digest(path):
    if path.stat().st_size > MAX_BYTES:
        raise ValueError('File exceeds the 64 MiB limit')
    checksum = hashlib.sha256()
    with path.open('rb') as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b''):
            checksum.update(block)
    return checksum.hexdigest()


def child(root, relative):
    # Reject links/junctions before resolving, including a destination parent.
    value = Path(relative)
    if value.is_absolute() or value.drive or not value.parts or any(part in ('.', '..') or ':' in part for part in value.parts):
        raise ValueError('Unsafe relative path')
    candidate = root
    for part in value.parts:
        candidate = candidate / part
        if candidate.is_symlink() or (hasattr(candidate, 'is_junction') and candidate.is_junction()):
            raise ValueError('Links and junctions are unsupported')
    if not candidate.resolve().is_relative_to(root):
        raise ValueError('Path escapes selected folder')
    return candidate


def plan(source, output):
    source = Path(source)
    if source.is_symlink() or (hasattr(source, 'is_junction') and source.is_junction()):
        raise ValueError('Choose a regular folder')
    root = source.resolve(strict=True)
    if root == Path(root.anchor) or not root.is_dir() or (root / '.git').exists():
        raise ValueError('Choose a disposable/non-repository folder')
    if Path(output).exists():
        raise FileExistsError('Choose a new plan path')
    entries, skipped = [], []
    files = []
    for item in root.iterdir():
        files.append(item)
        if len(files) > LIMIT:
            raise ValueError('Folder exceeds the 500-entry limit; choose a smaller folder')
    for item in sorted(files):
        if item == Path(output).resolve():
            continue
        if item.name.startswith('.') or not item.is_file() or item.is_symlink() or (hasattr(item, 'is_junction') and item.is_junction()):
            skipped.append({'name': item.name, 'reason': 'hidden_folder_or_link'})
            continue
        if item.stat().st_size > MAX_BYTES:
            skipped.append({'name': item.name, 'reason': 'size_limit'})
            continue
        category = CATEGORIES.get(item.suffix.lower(), 'Other')
        relative = str(Path(category) / item.name)
        target = child(root, relative)
        if target.exists():
            skipped.append({'name': item.name, 'reason': 'target_exists'})
            continue
        entries.append({'from': item.name, 'to': relative, 'sha256': digest(item)})
    data = {'schema_version': 1, 'root': str(root), 'moves': entries, 'skipped': skipped}
    dump_new(output, data)
    return data


def validate(data):
    if data.get('schema_version') != 1 or not isinstance(data.get('moves'), list) or len(data['moves']) > LIMIT:
        raise ValueError('Invalid plan/journal')
    root = Path(data['root'])
    if not root.is_absolute() or root.is_symlink() or (hasattr(root, 'is_junction') and root.is_junction()) or root.resolve(strict=True) != root:
        raise ValueError('Root is not a resolved regular folder')
    if root == Path(root.anchor) or not root.is_dir() or (root / '.git').exists():
        raise ValueError('Unsupported root')
    seen = set()
    for entry in data['moves']:
        source, target = child(root, entry['from']), child(root, entry['to'])
        if source.parent != root or target.parent.parent != root or target.parent.name not in set(CATEGORIES.values()) | {'Other'} or source.name != target.name:
            raise ValueError('Moves must retain filenames in one category subfolder')
        for path in (source, target):
            identity = str(path).casefold()
            if identity in seen:
                raise ValueError('Duplicate or overlapping move')
            seen.add(identity)
    return root


def apply(data, journal):
    root = validate(data)
    journal = Path(journal).resolve()
    if any(journal == child(root, entry[side]) for entry in data['moves'] for side in ('from', 'to')):
        raise ValueError('Journal conflicts with a move')
    for entry in data['moves']:
        source, target = child(root, entry['from']), child(root, entry['to'])
        if not source.is_file() or digest(source) != entry['sha256'] or target.exists():
            raise ValueError('Stale plan or target collision; nothing moved')
        if target.parent.exists() and not target.parent.is_dir():
            raise ValueError('Target category is not a folder')
    state = {'schema_version': 1, 'root': str(root), 'moves': [dict(entry, status='pending') for entry in data['moves']]}
    with journal.open('x', encoding='utf-8') as handle:
        def flush():
            handle.seek(0)
            json.dump(state, handle, ensure_ascii=True, indent=2)
            handle.truncate()
            handle.flush()
        flush()
        for entry in state['moves']:
            source, target = child(root, entry['from']), child(root, entry['to'])
            target.parent.mkdir(exist_ok=True)
            # Exclusive creation prevents overwrites, including races after preflight.
            with source.open('rb') as original, target.open('xb') as destination:
                for block in iter(lambda: original.read(1024 * 1024), b''):
                    destination.write(block)
            if digest(target) != entry['sha256'] or digest(source) != entry['sha256']:
                entry['status'] = 'conflict_copy_retained'
                flush()
                raise ValueError('Content changed during move; copies retained, inspect journal')
            entry['status'] = 'copied'
            flush()
            source.unlink()
            entry['status'] = 'moved'
            flush()
    return {'journal': str(journal), 'moved': len(state['moves'])}


def undo(journal):
    journal = Path(journal)
    if journal.is_symlink() or (hasattr(journal, 'is_junction') and journal.is_junction()):
        raise ValueError('Journal links are unsupported')
    state = json.loads(journal.read_text(encoding='utf-8'))
    root = validate(state)
    moves = [entry for entry in state['moves'] if entry.get('status') == 'moved']
    if any(entry.get('status') not in ('moved', 'pending', 'restored') for entry in state['moves']):
        raise ValueError('Interrupted copy requires inspection before undo')
    if any(entry.get('status') == 'pending' and child(root, entry['to']).exists() for entry in state['moves']):
        raise ValueError('Interrupted destination requires inspection')
    for entry in moves:
        source, target = child(root, entry['from']), child(root, entry['to'])
        if source.exists() or not target.is_file() or digest(target) != entry['sha256']:
            raise ValueError('Undo conflict; nothing restored')
    for entry in reversed(moves):
        source, target = child(root, entry['from']), child(root, entry['to'])
        with target.open('rb') as original, source.open('xb') as destination:
            for block in iter(lambda: original.read(1024 * 1024), b''):
                destination.write(block)
        if digest(source) != entry['sha256'] or digest(target) != entry['sha256']:
            raise ValueError('Undo content changed; copies retained')
        target.unlink()
        entry['status'] = 'restored'
        journal.write_text(json.dumps(state, ensure_ascii=True, indent=2), encoding='utf-8')
    return {'restored': len(moves), 'journal': str(journal)}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('command', choices=['plan', 'apply', 'undo'])
    parser.add_argument('--source', type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--plan', type=Path)
    parser.add_argument('--journal', type=Path)
    args = parser.parse_args()
    try:
        if args.command == 'plan' and args.source and args.output:
            result = plan(args.source, args.output)
        elif args.command == 'apply' and args.plan and args.journal:
            result = apply(json.loads(args.plan.read_text(encoding='utf-8-sig')), args.journal)
        elif args.command == 'undo' and args.journal:
            result = undo(args.journal)
        else:
            parser.error('Provide the paths required by this command')
        print(json.dumps(result, ensure_ascii=True))
    except (OSError, ValueError, KeyError, TypeError) as error:
        print(json.dumps({'status': 'failed', 'reason': str(error), 'instruction': 'Inspect the plan/journal; do not retry blindly.'}, ensure_ascii=True), file=sys.stderr)
        sys.exit(2)

#!/usr/bin/env python3
# Copyright (c) Microsoft Corporation. Licensed under the MIT License.
"""Create a self-contained source-anchored lesson without external resources."""
import argparse
import html
import json
import re
from pathlib import Path
import sys


def create(plan, output):
    title, passage, source = (plan.get(name) for name in ('title', 'passage', 'source'))
    questions = plan.get('questions', [])
    if not all(isinstance(value, str) and value.strip() for value in (title, passage, source)) or len(passage) > 30000:
        raise ValueError('Title, passage and source required; passage limit 30000 characters')
    if not isinstance(questions, list) or not 1 <= len(questions) <= 20:
        raise ValueError('Use 1 to 20 questions')
    for item in questions:
        choices = item.get('choices', [])
        answer = item.get('answer')
        if not isinstance(choices, list) or not 2 <= len(choices) <= 6 or any(not isinstance(s, str) or not s.strip() for s in choices):
            raise ValueError('Each question needs 2 to 6 nonempty choices')
        if type(answer) is not int or not 0 <= answer < len(choices):
            raise ValueError('Answer index is invalid')
        if not all(isinstance(item.get(k), str) and item[k].strip() for k in ('question', 'explanation', 'evidence')) or item['evidence'] not in passage:
            raise ValueError('Question, explanation and an exact passage evidence anchor required')
    data = json.dumps(questions, ensure_ascii=True).replace('<', '\\u003c')
    page = '''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>__TITLE__</title><style>body{font:18px/1.6 system-ui;max-width:850px;margin:auto;padding:24px;color:#172334;background:#f6f8fb}article,fieldset{background:white;border:1px solid #ccd5e0;border-radius:12px;padding:20px;margin:16px 0}label{display:block;margin:10px 0}button{font:inherit;padding:8px 16px;cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #1266ce}pre{white-space:pre-wrap;font:inherit}legend{font-weight:600}#score{font-weight:bold}</style>
<h1>__TITLE__</h1><p>Источник: __SOURCE__</p><article><h2>Материал</h2><pre>__PASSAGE__</pre></article><h2>Проверьте себя</h2><div id="quiz"></div><p id="score" role="status"></p>
<script>const questions=__QUESTIONS__;const results=new Map();const host=document.querySelector('#quiz');
questions.forEach((q,i)=>{const f=document.createElement('fieldset');const legend=document.createElement('legend');legend.textContent=q.question;f.append(legend);q.choices.forEach((text,j)=>{const label=document.createElement('label');const input=document.createElement('input');input.type='radio';input.name='q'+i;input.value=String(j);label.append(input,document.createTextNode(' '+text));f.append(label)});const b=document.createElement('button');b.textContent='Проверить';const feedback=document.createElement('p');feedback.setAttribute('role','status');b.addEventListener('click',()=>{const chosen=f.querySelector('input:checked');if(!chosen){feedback.textContent='Выберите ответ';return}const ok=Number(chosen.value)===q.answer;results.set(i,ok);feedback.textContent=(ok?'Верно. ':'Пока неверно. ')+q.explanation+' Опора на источник: '+q.evidence;document.querySelector('#score').textContent='Верно: '+[...results.values()].filter(Boolean).length+' из '+questions.length});f.append(b,feedback);host.append(f)});
</script></html>'''
    # A single pass never interprets placeholders embedded in user/source text.
    replacements = {'__QUESTIONS__': data, '__TITLE__': html.escape(title),
                    '__SOURCE__': html.escape(source), '__PASSAGE__': html.escape(passage)}
    page = re.sub(r'__(QUESTIONS|TITLE|SOURCE|PASSAGE)__', lambda match: replacements[match[0]], page)
    with Path(output).open('x', encoding='utf-8') as handle:
        handle.write(page)
    return {'output': str(output), 'questions': len(questions), 'evidence_anchors': 'checked', 'browser_check': 'not_performed'}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--plan', required=True, type=Path)
    parser.add_argument('--output', required=True, type=Path)
    args = parser.parse_args()
    try:
        print(json.dumps(create(json.loads(args.plan.read_text(encoding='utf-8-sig')), args.output)))
    except (OSError, ValueError, KeyError, TypeError) as error:
        print(json.dumps({'status': 'failed', 'reason': str(error)}, ensure_ascii=True), file=sys.stderr)
        sys.exit(2)

#!/usr/bin/env python3
# Copyright (c) Microsoft Corporation. All rights reserved.
# Licensed under the MIT License. See License.txt in the project root.
"""Deterministic local media operations. No network or Python packages required."""

import argparse
import hashlib
import json
import math
import re
import shutil
import subprocess
import sys
import threading
import time
from fractions import Fraction
from pathlib import Path

VERSION = "1.0.1"


def emit(stage, **data):
    print(json.dumps({"stage": stage, **data}, ensure_ascii=True), flush=True)


def save(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def load(path):
    return json.loads(Path(path).read_text(encoding="utf-8-sig"))


def tool(value):
    found = shutil.which(str(value))
    if not found:
        raise ValueError("Program missing: " + str(value))
    return str(Path(found).resolve())


def number(value, low, high, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or not low <= value <= high:
        raise ValueError("Invalid " + label)
    return value


def integer(value, low, high, label):
    number(value, low, high, label)
    if int(value) != value:
        raise ValueError(label + " must be an integer")
    return int(value)


def file(value):
    path = Path(value).expanduser().resolve()
    if not path.is_file():
        raise ValueError("File missing: " + str(path))
    return path


def fresh(value):
    path = Path(value).expanduser().resolve()
    if path.exists() and (not path.is_dir() or any(path.iterdir())):
        raise ValueError("Choose a new empty output directory")
    path.mkdir(parents=True, exist_ok=True)
    return path


def execute(command, log, timeout=300, capture=False, cwd=None):
    with log.open("ab") as errors:
        result = subprocess.run(command, stdout=subprocess.PIPE if capture else errors,
                                stderr=errors, timeout=timeout, cwd=cwd, check=False)
    if result.returncode:
        raise RuntimeError("Process exited %s; see %s" % (result.returncode, log))
    return result.stdout if capture else None


def probe(path, ffprobe, log):
    return json.loads(execute([ffprobe, "-v", "error", "-show_streams", "-show_format", "-of", "json", str(path)], log, capture=True))


def stream(info, kind):
    return next((row for row in info.get("streams", []) if row.get("codec_type") == kind), None)


def duration(info):
    return float(info.get("format", {}).get("duration") or (stream(info, "video") or stream(info, "audio") or {})["duration"])


def fingerprint(path):
    stat = path.stat()
    return {"path": str(path), "bytes": stat.st_size, "mtime_ns": stat.st_mtime_ns}


def sha(path):
    result = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            result.update(chunk)
    return result.hexdigest()


def render(command, log, seconds, timeout, cwd):
    started = time.monotonic()
    with log.open("ab") as errors:
        process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=errors, text=True, cwd=cwd)
        timer = threading.Timer(timeout, process.kill)
        timer.start()
        try:
            previous = -10
            for line in process.stdout:
                if line.startswith("out_time_us="):
                    try:
                        percent = min(99, int(int(line.split("=", 1)[1]) / 1_000_000 / seconds * 100))
                    except ValueError:
                        continue
                    if percent >= previous + 5:
                        emit("render", percent=max(0, percent))
                        previous = percent
            process.wait()
        finally:
            timer.cancel()
            process.stdout.close()
            if process.poll() is None:
                process.kill()
                process.wait()
    elapsed = time.monotonic() - started
    if process.returncode:
        raise RuntimeError("Render failed (exit %s, %.1f seconds); see %s" % (process.returncode, elapsed, log))
    return round(elapsed, 3)


def doctor(args):
    checks, programs, problems, capabilities = {}, {}, [], {}
    for name in ("ffmpeg", "ffprobe"):
        try:
            executable = tool(getattr(args, name))
            result = subprocess.run([executable, "-version"], capture_output=True, text=True, timeout=15)
            checks[name] = result.returncode == 0 and result.stdout.startswith(name + " version")
            if not checks[name]:
                raise ValueError("Not a working " + name)
            programs[name] = {"path": executable, "version": result.stdout.splitlines()[0]}
        except (OSError, ValueError, subprocess.SubprocessError) as error:
            checks[name] = False
            problems.append(str(error))
    if checks["ffmpeg"]:
        for option, required in (("filters", ("scale", "crop", "pad", "fps", "trim", "atrim", "concat", "overlay", "loudnorm", "afade", "xstack")),
                                 ("encoders", ("libx264", "aac", "mjpeg", "pcm_s16le"))):
            result = subprocess.run([programs["ffmpeg"]["path"], "-hide_banner", "-" + option], capture_output=True, text=True, timeout=15)
            available = set(re.findall(r"^\s*[A-Z.]{2,6}\s+(\w+)\s", result.stdout, re.MULTILINE))
            missing = sorted(set(required) - available)
            if option == "filters":
                capabilities["burn_in_captions"] = "subtitles" in available
            checks[option] = result.returncode == 0 and not missing
            if not checks[option]:
                problems.append("Missing FFmpeg %s: %s" % (option, ", ".join(missing)))
    report = {"skill": "media-toolkit", "version": VERSION, "python": sys.version.split()[0],
              "checks": checks, "programs": programs, "problems": problems, "capabilities": capabilities}
    emit("dependencies_ready" if all(checks.values()) else "dependencies_unavailable", **report)
    return all(checks.values())


def review(source, output, ffmpeg, ffprobe, expected=None, dimensions=None, audio=None, timeout=300):
    info = probe(source, ffprobe, output / "verify.log")
    video, sound = stream(info, "video"), stream(info, "audio")
    seconds = duration(info)
    if not video or seconds <= 0 or source.stat().st_size == 0:
        raise ValueError("Output is not a nonempty video")
    checks = {"nonempty": True, "dimensions": not dimensions or [video["width"], video["height"]] == dimensions,
              "duration": expected is None or abs(seconds - expected) <= .12,
              "audio": audio is None or bool(sound) == audio,
              "square_pixels": video.get("sample_aspect_ratio", "1:1") in ("1:1", "N/A")}
    frame_count = int(video["nb_frames"]) if str(video.get("nb_frames", "")).isdigit() else None
    if frame_count is not None and expected is not None:
        rate = Fraction(video.get("avg_frame_rate") or "0/1")
        checks["frame_count"] = abs(frame_count - round(expected * float(rate))) <= 1
    if audio is True and sound:
        checks["audio_duration"] = abs(float(sound.get("duration") or seconds) - seconds) <= .15
    execute([ffmpeg, "-v", "error", "-nostdin", "-i", str(source), "-f", "null", "-"], output / "verify.log", timeout=timeout)
    checks["decode"] = True
    samples = [seconds * fraction for fraction in (.1, .5, .9)]
    arguments = [ffmpeg, "-v", "error", "-nostdin", "-n"]
    for index, timestamp in enumerate(samples):
        frame = output / ("review_%d.jpg" % index)
        execute([ffmpeg, "-v", "error", "-nostdin", "-n", "-ss", str(timestamp), "-i", str(source),
                 "-frames:v", "1", "-vf", "scale=640:360:force_original_aspect_ratio=decrease,pad=640:360:(ow-iw)/2:(oh-ih)/2,setsar=1",
                 "-q:v", "3", str(frame)], output / "verify.log")
        if frame.stat().st_size < 100:
            raise ValueError("Review image is empty")
        arguments += ["-i", str(frame)]
    sheet = output / "review-sheet.jpg"
    execute(arguments + ["-filter_complex", "[0:v][1:v][2:v]xstack=inputs=3:layout=0_0|640_0|1280_0[out]",
                         "-map", "[out]", "-frames:v", "1", "-q:v", "3", str(sheet)], output / "verify.log")
    return {"status": "technical_pass_visual_review_required" if all(checks.values()) else "technical_failure",
            "file": str(source), "bytes": source.stat().st_size, "duration": seconds, "checks": checks,
            "width": video["width"], "height": video["height"], "frames": frame_count, "audio_codec": sound.get("codec_name") if sound else None,
            "sample_seconds": samples, "review_sheet": str(sheet)}


def segments(plan, seconds, fps):
    requested = plan.get("segments", [[0, seconds]])
    if not isinstance(requested, list) or not 1 <= len(requested) <= 50:
        raise ValueError("Provide between 1 and 50 retained intervals")
    rows, previous, offset = [], 0, 0
    for pair in requested:
        if not isinstance(pair, list) or len(pair) != 2:
            raise ValueError("Each retained interval is [start, end] in source seconds")
        begin, end = (number(value, 0, seconds + .05, "segment time") for value in pair)
        if begin < previous or end <= begin or end - begin < 1 / fps:
            raise ValueError("Retained intervals must be ordered, nonoverlapping and at least one frame")
        begin, end = round(begin * fps) / fps, min(round(end * fps) / fps, math.floor(seconds * fps + .01) / fps)
        if end <= begin:
            raise ValueError("Interval contains no complete frames")
        rows.append({"source_start": begin, "source_end": end, "output_start": offset, "output_end": offset + end - begin})
        offset += end - begin
        previous = end
    return rows, offset


def fit(width, height, mode="contain"):
    if mode not in ("contain", "cover"):
        raise ValueError("fit must be contain or cover")
    if mode == "cover":
        return "scale=%d:%d:force_original_aspect_ratio=increase,crop=%d:%d,setsar=1" % (width, height, width, height)
    return "scale=%d:%d:force_original_aspect_ratio=decrease,pad=%d:%d:(ow-iw)/2:(oh-ih)/2,setsar=1" % (width, height, width, height)


def edit(args):
    plan = load(args.plan)
    if not isinstance(plan, dict) or set(plan) - {"source", "segments", "width", "height", "fit", "crop", "audio", "audio_source", "webcam", "overlays", "captions"}:
        raise ValueError("Plan has unsupported fields; read the plan reference")
    source = file(plan["source"])
    output = fresh(args.output)
    ffmpeg, ffprobe = tool(args.ffmpeg), tool(args.ffprobe)
    before = {str(source): fingerprint(source)}
    info = probe(source, ffprobe, output / "prepare.log")
    video = stream(info, "video")
    if not video:
        raise ValueError("Source has no video")
    rate = Fraction(video.get("avg_frame_rate") if video.get("avg_frame_rate") not in (None, "0/0") else "30/1")
    fps = float(rate) if rate else 30
    number(fps, 1, 120, "source frame rate")
    rows, seconds = segments(plan, duration(info), fps)
    if seconds > 30 and not args.full:
        raise ValueError("Preview is limited to 30 seconds; use --full only for a requested full export")
    width = integer(plan.get("width", int(video["width"])), 64, 3840, "width")
    height = integer(plan.get("height", int(video["height"])), 64, 3840, "height")
    if width % 2 or height % 2:
        raise ValueError("Output dimensions must be even")
    graph, inputs = [], ["-i", str(source)]
    def add_input(path, still=False):
        actual = file(path)
        before[str(actual)] = fingerprint(actual)
        index = sum(1 for value in inputs if value == "-i")
        inputs.extend((["-loop", "1"] if still else []) + ["-i", str(actual)])
        return index
    def trim_track(index, media, prefix, preprocess=""):
        count = len(rows)
        split = "asplit" if media == "a" else "split"
        graph.append("[%d:%s]%s%s=%d%s" % (index, media, preprocess, split, count, "".join("[%sin%d]" % (prefix, i) for i in range(count))))
        for i, row in enumerate(rows):
            length = row["source_end"] - row["source_start"]
            filters = "atrim=start=%.9f:end=%.9f,asetpts=PTS-STARTPTS,afade=t=in:d=0.005,afade=t=out:st=%.9f:d=0.005" % (row["source_start"], row["source_end"], max(0, length - .005)) if media == "a" else "trim=start=%.9f:end=%.9f,setpts=PTS-STARTPTS" % (row["source_start"], row["source_end"])
            graph.append("[%sin%d]%s[%s%d]" % (prefix, i, filters, prefix, i))
        graph.append("%sconcat=n=%d:v=%d:a=%d[%sout]" % ("".join("[%s%d]" % (prefix, i) for i in range(count)), count, int(media == "v"), int(media == "a"), prefix))
    crop = plan.get("crop")
    crop_filter = ""
    if crop:
        if not isinstance(crop, dict) or set(crop) != {"x", "y", "width", "height"}:
            raise ValueError("crop must contain x, y, width and height")
        x = integer(crop["x"], 0, video["width"] - 2, "crop x")
        y = integer(crop["y"], 0, video["height"] - 2, "crop y")
        cw = integer(crop["width"], 2, video["width"] - x, "crop width")
        ch = integer(crop["height"], 2, video["height"] - y, "crop height")
        crop_filter = "crop=%d:%d:%d:%d," % (cw, ch, x, y)
    trim_track(0, "v", "main", "fps=%.9f,%s%s," % (fps, crop_filter, fit(width, height, plan.get("fit", "contain"))))
    visual = "mainout"
    audio_index = add_input(plan["audio_source"]) if plan.get("audio_source") else 0
    audio_info = probe(file(plan["audio_source"]), ffprobe, output / "prepare.log") if plan.get("audio_source") else info
    has_audio = bool(stream(audio_info, "audio"))
    if has_audio:
        if float(stream(audio_info, "audio").get("duration") or duration(audio_info)) + .05 < rows[-1]["source_end"]:
            raise ValueError("Audio ends before the retained source interval")
        trim_track(audio_index, "a", "voice")
    webcam = plan.get("webcam")
    if webcam:
        if not isinstance(webcam, dict) or set(webcam) - {"source", "size", "x", "y", "shape"}:
            raise ValueError("Unsupported webcam option; only a synchronized, fixed-position camera is supported")
        camera_index = add_input(webcam["source"])
        camera_info = probe(file(webcam["source"]), ffprobe, output / "prepare.log")
        if not stream(camera_info, "video") or duration(camera_info) + .05 < rows[-1]["source_end"]:
            raise ValueError("Camera has no video or ends too early; synchronize sources before editing")
        size = integer(webcam.get("size", 300), 32, min(width, height), "camera size")
        x = integer(webcam.get("x", width - size - 24), 0, width - size, "camera x")
        y = integer(webcam.get("y", height - size - 24), 0, height - size, "camera y")
        trim_track(camera_index, "v", "cam", "fps=%.9f,%s," % (fps, fit(size, size, "cover")))
        shape = webcam.get("shape", "circle")
        if shape not in ("circle", "square"):
            raise ValueError("Camera shape must be circle or square")
        if shape == "circle":
            graph.append("[camout]format=rgba,geq=r='r(X,Y)':g='g(X,Y)':b='b(X,Y)':a='255*clip((W/2-hypot(X-W/2,Y-H/2))/1.5,0,1)'[camera]")
            camera = "camera"
        else:
            camera = "camout"
        graph.append("[%s][%s]overlay=x=%d:y=%d:eof_action=pass[cameraout]" % (visual, camera, x, y))
        visual = "cameraout"
    overlays = plan.get("overlays", [])
    if not isinstance(overlays, list) or len(overlays) > 20:
        raise ValueError("At most 20 still overlays are supported")
    for i, row in enumerate(overlays):
        if not isinstance(row, dict) or set(row) - {"source", "start", "end", "width", "height", "x", "y"}:
            raise ValueError("Unsupported still overlay option")
        index = add_input(row["source"], still=True)
        start = number(row["start"], 0, seconds, "overlay start")
        end = number(row["end"], start + .01, seconds, "overlay end")
        ow = integer(row.get("width", width), 2, width, "overlay width")
        oh = integer(row.get("height", height), 2, height, "overlay height")
        x = integer(row.get("x", (width - ow) // 2), 0, width - ow, "overlay x")
        y = integer(row.get("y", (height - oh) // 2), 0, height - oh, "overlay y")
        graph.append("[%d:v]scale=%d:%d:force_original_aspect_ratio=decrease,format=rgba[graphic%d]" % (index, ow, oh, i))
        graph.append("[%s][graphic%d]overlay=x=%d:y=%d:enable='between(t,%.9f,%.9f)':eof_action=pass[overlay%d]" % (visual, i, x, y, start, end, i))
        visual = "overlay%d" % i
    if plan.get("captions"):
        filters = subprocess.run([ffmpeg, "-hide_banner", "-filters"], capture_output=True, text=True, timeout=15, check=True)
        if not re.search(r"^\s*[A-Z.]{2,6}\s+subtitles\s", filters.stdout, re.MULTILINE):
            raise ValueError("Burn-in captions need FFmpeg subtitles/libass; on macOS use the ffmpeg-full executable")
        captions = file(plan["captions"])
        before[str(captions)] = fingerprint(captions)
        if captions.suffix.lower() != ".srt":
            raise ValueError("Burn-in captions must be SRT")
        shutil.copyfile(captions, output / "captions.srt")
        graph.append("[%s]subtitles=filename=captions.srt[subtitled]" % visual)
        visual = "subtitled"
    graph.append("[%s]format=yuv420p,setsar=1[video]" % visual)
    normalization = None
    audio_filters = plan.get("audio", {})
    if not isinstance(audio_filters, dict) or set(audio_filters) - {"normalize"} or not isinstance(audio_filters.get("normalize", False), bool):
        raise ValueError("audio.normalize must be boolean")
    if audio_filters.get("normalize"):
        if not has_audio:
            raise ValueError("Cannot normalize a missing audio stream")
        voice_graph = ";".join(row for row in graph if "[voice" in row)
        measure_log = output / "loudness-measure.log"
        execute([ffmpeg, "-hide_banner", "-nostdin", *inputs, "-filter_complex", voice_graph + ";[voiceout]loudnorm=I=-16:TP=-1.5:LRA=11:print_format=json[measure]",
                 "-map", "[measure]", "-f", "null", "-"], measure_log, timeout=args.timeout, cwd=output)
        text = measure_log.read_text(errors="replace")
        blocks = re.findall(r'\{\s*"input_i".*?\}', text, re.DOTALL)
        if not blocks:
            raise ValueError("FFmpeg did not return loudness measurements")
        normalization = json.loads(blocks[-1])
        values = [float(normalization[key]) for key in ("input_i", "input_tp", "input_lra", "input_thresh", "target_offset")]
        if not all(math.isfinite(value) for value in values):
            raise ValueError("Cannot normalize silent or invalid audio")
        graph.append("[voiceout]loudnorm=I=-16:TP=-1.5:LRA=11:measured_I=%s:measured_TP=%s:measured_LRA=%s:measured_thresh=%s:offset=%s:linear=false[audio]" % tuple(values))
    elif has_audio:
        graph.append("[voiceout]anull[audio]")
    graph_path = output / "filter.txt"
    graph_path.write_text(";\n".join(graph), encoding="utf-8")
    target = output / "preview.mp4"
    command = [ffmpeg, "-hide_banner", "-nostdin", "-n", "-filter_complex_threads", "2", *inputs,
               "-/filter_complex", str(graph_path), "-map", "[video]"]
    if has_audio:
        command += ["-map", "[audio]", "-c:a", "aac", "-b:a", "192k", "-ar", "48000"]
    command += ["-t", "%.9f" % seconds, "-c:v", "libx264", "-preset", "fast", "-crf", "20", "-pix_fmt", "yuv420p",
                "-movflags", "+faststart", "-progress", "pipe:1", "-nostats", str(target)]
    save(output / "plan.json", plan)
    shutil.copyfile(Path(__file__), output / "reproduce.py")
    save(output / "command.json", command)
    save(output / "edit-map.json", {"version": VERSION, "segments": rows, "duration": seconds, "inputs": before})
    emit("render", output=str(target), duration=seconds)
    elapsed = render(command, output / "render.log", seconds, args.timeout, output)
    report = review(target, output, ffmpeg, ffprobe, seconds, [width, height], has_audio, args.timeout)
    report.update({"skill": "media-toolkit", "version": VERSION, "render_seconds": elapsed,
                   "loudness_measurement": normalization, "loudness_measurement_stage": "first_pass",
                   "edit_map": str(output / "edit-map.json")})
    report["checks"]["inputs_unchanged"] = all(fingerprint(Path(path)) == stamp for path, stamp in before.items())
    if not all(report["checks"].values()):
        report["status"] = "technical_failure"
    save(output / "report.json", report)
    emit(report["status"], file=str(target), report=str(output / "report.json"), review_sheet=report["review_sheet"], render_seconds=elapsed)
    if report["status"] == "technical_failure":
        raise RuntimeError("Technical validation failed; see report.json")


def transcribe(args):
    source, model = file(args.source), file(args.model)
    ffmpeg, whisper = tool(args.ffmpeg), tool(args.whisper)
    identity = {"source": fingerprint(source), "model": fingerprint(model), "language": args.language, "version": VERSION}
    key = hashlib.sha256(json.dumps(identity, sort_keys=True).encode()).hexdigest()
    cache = Path(args.cache).resolve() / key
    manifest_path = cache / "cache.json"
    if manifest_path.is_file():
        manifest = load(manifest_path)
        if manifest["identity"] == identity and all((cache / name).is_file() and sha(cache / name) == digest for name, digest in manifest["files"].items()):
            emit("transcript_cached", cache=str(cache), srt=str(cache / "transcript.srt"), text=str(cache / "transcript.txt"))
            return
    cache.mkdir(parents=True, exist_ok=True)
    # A failed attempt is recoverable in its dedicated cache directory. No media source is overwritten.
    audio = cache / "analysis.wav"
    if audio.exists():
        audio.unlink()
    execute([ffmpeg, "-v", "error", "-nostdin", "-n", "-i", str(source), "-vn", "-ac", "1", "-ar", "16000", "-c:a", "pcm_s16le", str(audio)], cache / "extract.log", timeout=args.timeout)
    started = time.monotonic()
    execute([whisper, "-m", str(model), "-f", str(audio), "-l", args.language, "-otxt", "-osrt", "-ojf", "-of", str(cache / "transcript")], cache / "transcribe.log", timeout=args.timeout)
    files = {}
    for suffix in ("txt", "srt", "json"):
        path = cache / ("transcript." + suffix)
        if not path.is_file() or path.stat().st_size == 0:
            raise ValueError("Transcriber did not produce a nonempty " + suffix)
        files[path.name] = sha(path)
    save(manifest_path, {"identity": identity, "files": files, "seconds": round(time.monotonic() - started, 3)})
    emit("transcribed", cache=str(cache), srt=str(cache / "transcript.srt"), text=str(cache / "transcript.txt"))


def captions(args):
    rows = load(args.cues)
    if not isinstance(rows, list) or not rows or len(rows) > 10000:
        raise ValueError("Provide a nonempty list of caption cues")
    output = fresh(args.output)
    def stamp(value, separator):
        milliseconds = round(value * 1000)
        seconds, ms = divmod(milliseconds, 1000)
        minutes, sec = divmod(seconds, 60)
        hours, minute = divmod(minutes, 60)
        return "%02d:%02d:%02d%s%03d" % (hours, minute, sec, separator, ms)
    srt, vtt, previous = [], ["WEBVTT\n"], 0
    for i, row in enumerate(rows):
        begin = number(row["start"], previous, 86400, "caption start")
        end = number(row["end"], begin + .001, 86400, "caption end")
        text = row["text"]
        if not isinstance(text, str) or not text.strip() or "-->" in text or "\x00" in text:
            raise ValueError("Invalid caption text")
        srt.append("%d\n%s --> %s\n%s\n" % (i + 1, stamp(begin, ","), stamp(end, ","), text.strip()))
        vtt.append("%s --> %s\n%s\n" % (stamp(begin, "."), stamp(end, "."), text.strip()))
        previous = end
    (output / "captions.srt").write_text("\n".join(srt), encoding="utf-8")
    (output / "captions.vtt").write_text("\n".join(vtt), encoding="utf-8")
    emit("captions_exported", srt=str(output / "captions.srt"), vtt=str(output / "captions.vtt"), cues=len(rows))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--ffmpeg", default="ffmpeg")
    parser.add_argument("--ffprobe", default="ffprobe")
    commands = parser.add_subparsers(dest="mode", required=True)
    commands.add_parser("doctor")
    edit_parser = commands.add_parser("edit")
    edit_parser.add_argument("--plan", required=True)
    edit_parser.add_argument("--output", required=True)
    edit_parser.add_argument("--full", action="store_true")
    edit_parser.add_argument("--timeout", type=int, default=300)
    verify_parser = commands.add_parser("verify")
    verify_parser.add_argument("--source", required=True)
    verify_parser.add_argument("--output", required=True)
    verify_parser.add_argument("--expected-duration", type=float)
    verify_parser.add_argument("--timeout", type=int, default=300)
    transcript_parser = commands.add_parser("transcribe")
    transcript_parser.add_argument("--source", required=True)
    transcript_parser.add_argument("--model", required=True)
    transcript_parser.add_argument("--whisper", default="whisper-cli")
    transcript_parser.add_argument("--language", default="ru")
    transcript_parser.add_argument("--cache", required=True)
    transcript_parser.add_argument("--timeout", type=int, default=1800)
    caption_parser = commands.add_parser("captions")
    caption_parser.add_argument("--cues", required=True)
    caption_parser.add_argument("--output", required=True)
    args = parser.parse_args()
    try:
        if args.mode == "doctor":
            return 0 if doctor(args) else 1
        if args.mode == "verify":
            out = fresh(args.output)
            report = review(file(args.source), out, tool(args.ffmpeg), tool(args.ffprobe), args.expected_duration, timeout=args.timeout)
            save(out / "report.json", report)
            emit(report["status"], report=str(out / "report.json"), review_sheet=report["review_sheet"])
            return 0 if all(report["checks"].values()) else 1
        {"edit": edit, "transcribe": transcribe, "captions": captions}[args.mode](args)
        return 0
    except (OSError, KeyError, TypeError, ValueError, RuntimeError, subprocess.SubprocessError) as error:
        emit("failed", error=str(error))
        return 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# Copyright (c) Microsoft Corporation. Licensed under the MIT License.
"""Simple editable PPTX and narrow format-preserving text replacement."""
import argparse
import json
from pathlib import Path
import sys


def inspect(path):
    from pptx import Presentation
    book = Presentation(path)
    return {'slides': [{'number': i + 1, 'text': [shape.text for shape in slide.shapes if shape.has_text_frame]} for i, slide in enumerate(book.slides)], 'visual_check': 'not_performed'}


def save(book, output):
    with Path(output).open('xb') as handle:
        book.save(handle)
    return inspect(output)


def create(plan, output):
    from pptx import Presentation
    from pptx.util import Inches, Pt
    from pptx.dml.color import RGBColor
    slides = plan.get('slides', [])
    if not 1 <= len(slides) <= 30:
        raise ValueError('Use 1 to 30 slides')
    # Validate all content before creating the output.
    for data in slides:
        if not isinstance(data.get('title'), str) or not 1 <= len(data['title']) <= 90:
            raise ValueError('A short title is required')
        bullets = data.get('bullets', [])
        if not isinstance(bullets, list) or len(bullets) > 6 or any(not isinstance(s, str) or len(s) > 150 for s in bullets):
            raise ValueError('Use up to six bullets of at most 150 characters')
        if not isinstance(data.get('source', ''), str) or len(data.get('source', '')) > 180:
            raise ValueError('Source footer is too long')
    book = Presentation()
    book.slide_width, book.slide_height = Inches(13.333), Inches(7.5)
    for i, data in enumerate(slides):
        slide = book.slides.add_slide(book.slide_layouts[6])
        title = slide.shapes.add_textbox(Inches(.7), Inches(.55), Inches(11.9), Inches(1.25)).text_frame
        title.word_wrap = True
        title.paragraphs[0].text = data['title']
        title.paragraphs[0].font.size = Pt(30)
        title.paragraphs[0].font.bold = True
        body = slide.shapes.add_textbox(Inches(.8), Inches(2), Inches(11.6), Inches(4.3)).text_frame
        body.word_wrap = True
        for j, text in enumerate(data.get('bullets', [])):
            paragraph = body.paragraphs[0] if j == 0 else body.add_paragraph()
            paragraph.text = text
            paragraph.font.size = Pt(21)
            paragraph.space_after = Pt(15)
        footer = slide.shapes.add_textbox(Inches(.8), Inches(6.7), Inches(11.6), Inches(.55)).text_frame
        footer.word_wrap = True
        footer.paragraphs[0].text = str(i + 1) + ' | ' + data.get('source', '')
        footer.paragraphs[0].font.size = Pt(10)
        footer.paragraphs[0].font.color.rgb = RGBColor(90, 90, 90)
    return save(book, output)


def replace(source, old, new, output):
    from pptx import Presentation
    if not old or not new or len(new) > 150 or '\n' in new:
        raise ValueError('Use a short nonempty single-line replacement')
    book = Presentation(source)
    matches = [shape for slide in book.slides for shape in slide.shapes if shape.has_text_frame and shape.text == old]
    if len(matches) != 1:
        raise ValueError('Text must match exactly one shape')
    paragraphs = matches[0].text_frame.paragraphs
    if len(paragraphs) != 1 or len(paragraphs[0].runs) != 1:
        raise ValueError('Rich-text replacement requires a separate copy-based edit')
    paragraphs[0].runs[0].text = new
    return save(book, output)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('command', choices=['create', 'inspect', 'replace-text'])
    parser.add_argument('source', nargs='?')
    parser.add_argument('--plan', type=Path)
    parser.add_argument('--old')
    parser.add_argument('--new')
    parser.add_argument('--output', type=Path)
    args = parser.parse_args()
    if args.command == 'create':
        if not args.plan or not args.output:
            parser.error('--plan and --output required')
        result = create(json.loads(args.plan.read_text(encoding='utf-8-sig')), args.output)
    elif args.command == 'replace-text':
        if not args.source or not args.old or not args.new or not args.output:
            parser.error('source, --old, --new and --output required')
        result = replace(args.source, args.old, args.new, args.output)
    else:
        if not args.source:
            parser.error('source required')
        result = inspect(args.source)
    print(json.dumps(result, ensure_ascii=True))


if __name__ == '__main__':
    try:
        main()
    except (OSError, ValueError, ImportError, KeyError) as error:
        print(json.dumps({'status': 'failed', 'reason': str(error)}, ensure_ascii=True), file=sys.stderr)
        sys.exit(2)

#!/usr/bin/env python3
# Copyright (c) Microsoft Corporation. Licensed under the MIT License.
"""Bounded CSV/XLSX inspection, merge and reconciliation. Never overwrites input."""
import argparse
from collections import Counter, defaultdict
import csv
from decimal import Decimal, InvalidOperation
import json
from pathlib import Path
import sys

LIMIT = 50000


def read(path, sheet=None, delimiter=','):
    path = Path(path)
    if path.stat().st_size > 32 * 1024**2:
        raise ValueError('Input exceeds 32 MiB')
    if path.suffix.lower() in ('.csv', '.tsv'):
        with path.open(encoding='utf-8-sig', newline='') as handle:
            rows = []
            for row in csv.reader(handle, delimiter='\t' if path.suffix.lower() == '.tsv' else delimiter):
                rows.append(row)
                if len(rows) > LIMIT + 1:
                    raise ValueError('Row limit exceeded')
    elif path.suffix.lower() == '.xlsx':
        from openpyxl import load_workbook
        book = load_workbook(path, read_only=True, data_only=False, keep_links=False)
        try:
            page = book[sheet] if sheet else book.worksheets[0]
            if (page.max_row or 0) > LIMIT + 1 or (page.max_column or 0) > 200:
                raise ValueError('Worksheet dimensions exceed row/column limits')
            rows = []
            for row in page.iter_rows(values_only=True):
                rows.append(list(row))
                if len(rows) > LIMIT + 1:
                    raise ValueError('Row limit exceeded')
        finally:
            book.close()
    else:
        raise ValueError('Use CSV, TSV or XLSX; legacy XLS/macros are unsupported')
    if not rows or len(rows[0]) > 200:
        raise ValueError('Empty table or too many columns')
    headers = [str(value).strip() if value is not None else '' for value in rows[0]]
    if not all(headers) or len(set(headers)) != len(headers):
        raise ValueError('Headers must be unique and nonempty')
    result = []
    for row in rows[1:]:
        if not any(value is not None and value != '' for value in row):
            continue
        if len(row) > len(headers):
            raise ValueError('Row has more cells than headers')
        result.append(dict(zip(headers, row + [None] * (len(headers) - len(row)))))
    return headers, result


def formula(value):
    return isinstance(value, str) and value.startswith('=')


def key(value):
    return '' if value is None else str(value).strip()


def amount(value):
    if isinstance(value, bool) or value is None or ',' in str(value):
        raise ValueError('Amount must use an explicit decimal point')
    try:
        result = Decimal(str(value).strip())
    except InvalidOperation as error:
        raise ValueError('Invalid amount') from error
    if not result.is_finite():
        raise ValueError('Non-finite amount')
    return result


def write(path, headers, records):
    path = Path(path)
    if path.exists():
        raise FileExistsError('Choose a new output file')
    if path.suffix.lower() == '.xlsx':
        from openpyxl import Workbook
        book = Workbook()
        page = book.active
        page.title = 'Results'
        for index, values in enumerate([headers, *records], 1):
            page.append(values)
            for cell in page[index]:
                if isinstance(cell.value, str):
                    cell.data_type = 's'
        page.freeze_panes = 'A2'
        page.auto_filter.ref = page.dimensions
        with path.open('xb') as handle:
            book.save(handle)
        book.close()
    elif path.suffix.lower() == '.csv':
        with path.open('x', encoding='utf-8-sig', newline='') as handle:
            # Neutralize active cells on opening CSV in a spreadsheet application.
            safe = lambda value: "'" + value if isinstance(value, str) and value.startswith(('=', '+', '-', '@', '\t', '\r')) else value
            writer = csv.writer(handle)
            writer.writerow([safe(value) for value in headers])
            writer.writerows([[safe(value) for value in row] for row in records])
    else:
        raise ValueError('Output must be CSV or XLSX')


def operate(command, paths, output=None, key_column=None, amount_column=None, sheet=None, delimiter=','):
    tables = [read(path, sheet, delimiter) for path in paths]
    if command == 'inspect':
        headers, rows = tables[0]
        return {'columns': headers, 'rows': len(rows), 'formula_cells': sum(formula(value) for row in rows for value in row.values()), 'sample': rows[:3], 'formula_recalculation': False}
    if any(formula(value) for _, rows in tables for row in rows for value in row.values()):
        raise ValueError('Formula input requires a recalculated values export')
    if any(key_column not in headers for headers, _ in tables):
        raise ValueError('Key column is absent')
    records = []
    if command == 'merge':
        headers = tables[0][0]
        if {'_source', '_key_status'} & set(headers):
            raise ValueError('Input uses reserved merge metadata columns')
        if any(columns != headers for columns, _ in tables):
            raise ValueError('Merge requires identical ordered headers')
        counts = Counter(key(row[key_column]) for _, rows in tables for row in rows)
        for path, (_, rows) in zip(paths, tables):
            for row in rows:
                value = key(row[key_column])
                records.append([Path(path).name, 'missing_key' if not value else 'duplicate_key' if counts[value] > 1 else 'unique', *row.values()])
        write(output, ['_source', '_key_status', *headers], records)
        return {'input_rows': sum(len(rows) for _, rows in tables), 'output_rows': len(records), 'duplicates_preserved': True}
    if len(tables) != 2 or any(amount_column not in headers for headers, _ in tables):
        raise ValueError('Reconciliation requires two tables and an amount column')
    groups = []
    for _, rows in tables:
        grouped = defaultdict(list)
        for row in rows:
            grouped[key(row[key_column])].append(row)
        groups.append(grouped)
    for identity in sorted(groups[0].keys() | groups[1].keys()):
        left, right = groups[0].get(identity, []), groups[1].get(identity, [])
        status = 'invalid_key' if not identity else 'ambiguous' if len(left) > 1 or len(right) > 1 else 'left_only' if not right else 'right_only' if not left else 'matched'
        a = b = delta = ''
        try:
            a = str(amount(left[0][amount_column])) if len(left) == 1 else ''
            b = str(amount(right[0][amount_column])) if len(right) == 1 else ''
            if status == 'matched':
                delta = str(Decimal(a) - Decimal(b))
                status = 'matched' if Decimal(delta) == 0 else 'amount_difference'
        except ValueError:
            status = status if status in ('ambiguous', 'invalid_key') else 'invalid_amount'
        records.append([identity, status, len(left), len(right), a, b, delta])
    write(output, [key_column, 'status', 'left_rows', 'right_rows', 'left_amount', 'right_amount', 'difference'], records)
    return {'input_rows': [len(rows) for _, rows in tables], 'keys': len(records), 'statuses': dict(Counter(row[1] for row in records)), 'output': str(output)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('command', choices=['inspect', 'merge', 'reconcile'])
    parser.add_argument('paths', nargs='+')
    parser.add_argument('--key')
    parser.add_argument('--amount')
    parser.add_argument('--sheet')
    parser.add_argument('--delimiter', default=',')
    parser.add_argument('--output', type=Path)
    args = parser.parse_args()
    if args.command != 'inspect' and (not args.key or not args.output):
        parser.error('--key and --output required')
    if args.command == 'reconcile' and not args.amount:
        parser.error('--amount required for reconciliation')
    if args.command == 'inspect' and len(args.paths) != 1:
        parser.error('Inspect one file at a time')
    print(json.dumps(operate(args.command, args.paths, args.output, args.key, args.amount, args.sheet, args.delimiter), ensure_ascii=True, default=str))


if __name__ == '__main__':
    try:
        main()
    except (OSError, ValueError, ImportError, KeyError) as error:
        print(json.dumps({'status': 'failed', 'reason': str(error)}, ensure_ascii=True), file=sys.stderr)
        sys.exit(2)
